package dev.alien.client.cosmetic.neon;
import com.google.gson.Gson;
import dev.alien.client.config.*;
import dev.alien.client.cosmetic.*;
import dev.alien.client.cosmetic.mesh.*;
import org.junit.*;import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
public class NeonTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void nullStyleMigratesWithoutEnablingCosmeticsOrChangingOldFields(){ClientConfig c=new Gson().fromJson("{\"cosmetics\":{\"enabled\":false,\"self\":{\"hat\":\"SAKURA\",\"back\":\"CAPE\",\"neon\":null,\"color\":12345}}}",ClientConfig.class);c.normalize();assertFalse(c.cosmetics.enabled);assertEquals("SAKURA",c.cosmetics.self.hat);assertEquals(12345,c.cosmetics.self.color);assertNotNull(c.cosmetics.self.neon);}
 @Test public void nonFiniteAndMaliciousImportsAreBounded(){NeonDesign d=new NeonDesign();d.intensity=Float.NaN;d.radius=Float.POSITIVE_INFINITY;d.color=-1;d.preset="missing";d.normalize();assertEquals(.85,d.intensity,.000001);assertEquals(12,d.radius,0);assertEquals(0xffffff,d.color);assertEquals("Custom",d.preset);d.intensity=999;d.radius=-1;d.normalize();assertEquals(1.5,d.intensity,0);assertEquals(4,d.radius,0);}
 @Test public void copyDoesNotShareTheMutableStyle(){CosmeticConfig.Accessory a=new CosmeticConfig.Accessory(),copy=a.copy();a.neon.preset("Crimson");assertEquals("Cyber",copy.neon.preset);assertNotEquals(a.neon.color,copy.neon.color);}
 @Test public void newMeshesAndNeonPersistWithMusicEmotesAndOldLookSlots()throws Exception{ConfigStore s=new ConfigStore(temp.newFolder());s.load();CosmeticConfig.Accessory a=s.config().cosmetics.self;a.back="DRAGON_WINGS";a.hat="HALO";a.neon.preset("Crimson");a.neon.intensity=1.3f;a.neon.bloom=false;s.config().cosmetics.saveLook(2,a);s.config().emotes.slots[0]="take_the_l";s.config().hud.music.style="Transparent";s.saveProfile("neon");s.resetDefaults();assertTrue(s.loadProfile("neon"));a=s.config().cosmetics.self;assertEquals("DRAGON_WINGS",a.back);assertEquals("HALO",a.hat);assertEquals(1.3,a.neon.intensity,.000001);assertFalse(a.neon.bloom);assertEquals(0xFF346A,a.neon.color);assertEquals("Transparent",s.config().hud.music.style);assertEquals("take_the_l",s.config().emotes.slots[0]);a.neon.color=0;assertEquals(0xFF346A,s.config().cosmetics.loadLook(2).neon.color);}
 @Test public void roundedHaloAndBothArticulatedWingSegmentsHaveFiniteUnitNormals(){for(Mesh m:new Mesh[]{NeonMeshes.HALO,NeonMeshes.dragon(true,false),NeonMeshes.dragon(false,false),NeonMeshes.dragon(true,true),NeonMeshes.dragon(false,true)}){assertTrue(m.vertexCount()>100);assertTrue(m.vertexCount()<12000);assertEquals(0,m.vertexCount()%3);for(int i=0;i<m.vertexCount();i++){assertTrue(Float.isFinite(m.x(i))&&Float.isFinite(m.y(i))&&Float.isFinite(m.z(i)));assertTrue(Math.abs(m.x(i))<24&&Math.abs(m.y(i))<16&&Math.abs(m.z(i))<8);assertEquals(1,m.nx(i)*m.nx(i)+m.ny(i)*m.ny(i)+m.nz(i)*m.nz(i),.00001);}}}
 @Test public void oppositeDragonWingsHaveMirroredBoundsAndCachedGeometry(){Mesh a=NeonMeshes.dragon(true,true),b=NeonMeshes.dragon(false,true);assertSame(a,NeonMeshes.dragon(true,true));assertEquals(a.vertexCount(),b.vertexCount());java.util.Set<String> left=new java.util.HashSet<String>(),right=new java.util.HashSet<String>();for(int i=0;i<a.vertexCount();i++){left.add(Math.round(a.x(i)*10000)+"/"+Math.round(a.y(i)*10000)+"/"+Math.round(a.z(i)*10000));right.add(Math.round(-b.x(i)*10000)+"/"+Math.round(b.y(i)*10000)+"/"+Math.round(b.z(i)*10000));}assertEquals(left,right);}
}
